"""Product analytics dashboard: conversion statistics over customer sessions."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    for n, line in enumerate(lines, 1):
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        parts = [p.strip() for p in text.split(",")]
        if len(parts) != 3:
            raise ValueError(f"line {n}: expected 3 fields, got {len(parts)}")
        id_, day, flag = parts
        try:
            day = int(day)
        except ValueError:
            raise ValueError(f"line {n}: day is not an integer: {day!r}") from None
        if flag == "1":
            converted = True
        elif flag == "0":
            converted = False
        elif flag == "":
            converted = None
        else:
            raise ValueError(f"line {n}: invalid converted value: {flag!r}")
        out.append({"id": id_, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if e["converted"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts
